local({
  band <- as.numeric(INCADIA5)
  band[!band %in% 1:5] <- NA
  ref <- !is.na(band) & as.numeric(DHHAGAGE) %in% 1:2
  codes <- 1:5
  x <- band[ref]
  r <- vapply(codes, function(b) mean(x < b) + mean(x == b) / 2, numeric(1))
  mid <- if (any(r >= 0.4 & r <= 0.6)) {
    r >= 0.4 & r <= 0.6
  } else {
    abs(r - 0.5) == min(abs(r - 0.5))
  }
  level <- ifelse(mid, "Medium", ifelse(r < 0.4, "Low", "High"))
  out <- rep("Unknown", length(band))
  hit <- !is.na(band)
  out[hit] <- level[match(band[hit], codes)]
  out
})

local({
  m <- vapply(list(RACA_2A, RACA_2B, RACA_2C), as.numeric, numeric(length(RACA_2A)))
  case_when(rowSums(m == 1 | m == 2) > 0 ~ TRUE, rowSums(m == 3) > 0 ~ FALSE, .default = NA)
})
